adcs_status_t status = ADCS_OK;
adcs_vec3_t momentum_nms = {0};
adcs_vec3_t error_nms = {0};
adcs_vec3_t torque_nm = {0};
double norm_error = 0.0;
unint32 sat_mask = 0;
int is_fault = 0;

// 1. Validate Inputs
if (!mb_input.enable || (mb_input.enable & ~1U)) {
    is_fault = 1;
} else if (mb_input.wheels == NULL || mb_input.wheel_count != 4) {
    is_fault = 1;
} else {
    // Validate Config
    if (!isfinite(mb_config.target_nms.x) || !isfinite(mb_config.target_nms.y) || !isfinite(mb_config.target_nms.z) ||
        !isfinite(mb_config.target_slew_nms_per_cycle) || mb_config.target_slew_nms_per_cycle <= 0.0 ||
        !isfinite(mb_config.enter_error_nms) || !isfinite(mb_config.exit_error_nms) ||
        mb_config.enter_error_nms < 0.0 || mb_config.exit_error_nms < 0.0 ||
        mb_config.enter_error_nms > mb_config.exit_error_nms ||
        !isfinite(mb_config.kp_s_inv) || !isfinite(mb_config.ki_s2_inv) ||
        mb_config.kp_s_inv < 0.0 || mb_config.ki_s2_inv < 0.0 ||
        !isfinite(mb_config.dt_s) || mb_config.dt_s <= 0.0 ||
        !isfinite(mb_config.integral_limit_nms_s) || mb_config.integral_limit_nms_s <= 0.0 ||
        !isfinite(mb_config.torque_limit_nm) || mb_config.torque_limit_nm <= 0.0 ||
        !isfinite(mb_config.max_wheel_speed_rad_s) || mb_config.max_wheel_speed_rad_s <= 0.0 ||
        mb_config.settle_cycles < 1 || mb_config.settle_cycles > 20) {
        is_fault = 1;
    } else {
        // Validate Wheel Speeds
        for (size_t i = 0; i < 4; ++i) {
            if (!isfinite(mb_input.wheels[i].speed_rad_s) || fabs(mb_input.wheels[i].speed_rad_s) > mb_config.max_wheel_speed_rad_s) {
                is_fault = 1;
                break;
            }
        }
    }
}

if (is_fault) {
    mb_state.mode = MB_FAULT;
    mb_output.mode = MB_FAULT;
    mb_output.settled = 0;
    mb_output.saturation_mask = 0;
    mb_output.momentum_nms = (adcs_vec3_t){0};
    mb_output.commanded_target_nms = (adcs_vec3_t){0};
    mb_output.error_nms = (adcs_vec3_t){0};
    mb_output.integral_error_nms_s = (adcs_vec3_t){0};
    mb_output.torque_nm = (adcs_vec3_t){0};
    return;
}

// 2. Initialize on First Enable
if (!mb_state.target_initialized) {
    status = adcs_wheel_momentum(mb_input.wheels, mb_input.wheel_count, &momentum_nms);
    if (status != ADCS_OK) {
         mb_state.mode = MB_FAULT;
         mb_output.mode = MB_FAULT;
         mb_output.settled = 0;
         mb_output.saturation_mask = 0;
         mb_output.momentum_nms = (adcs_vec3_t){0};
         mb_output.commanded_target_nms = (adcs_vec3_t){0};
         mb_output.error_nms = (adcs_vec3_t){0};
         mb_output.integral_error_nms_s = (adcs_vec3_t){0};
         mb_output.torque_nm = (adcs_vec3_t){0};
         return;
    }
    mb_state.commanded_target_nms = momentum_nms;
    mb_state.integral_error_nms_s = (adcs_vec3_t){0};
    mb_state.settled = 0;
    mb_state.target_initialized = 1;
    mb_state.mode = MB_RAMP;
}

// 3. Compute Cluster Momentum
status = adcs_wheel_momentum(mb_input.wheels, mb_input.wheel_count, &momentum_nms);
if (status != ADCS_OK) {
     mb_state.mode = MB_FAULT;
     mb_output.mode = MB_FAULT;
     mb_output.settled = 0;
     mb_output.saturation_mask = 0;
     mb_output.momentum_nms = (adcs_vec3_t){0};
     mb_output.commanded_target_nms = (adcs_vec3_t){0};
     mb_output.error_nms = (adcs_vec3_t){0};
     mb_output.integral_error_nms_s = (adcs_vec3_t){0};
     mb_output.torque_nm = (adcs_vec3_t){0};
     return;
}

// 4. Detect New Target Change (if in BIAS or HOLD)
if (mb_state.mode == MB_BIAS || mb_state.mode == MB_HOLD) {
    adcs_vec3_t diff = adcs_vec3_sub(&mb_config.target_nms, &mb_state.commanded_target_nms);
    if (adcs_vec3_norm(&diff) > ADCS_EPS_NORM) {
        mb_state.mode = MB_RAMP;
        mb_state.settled = 0;
        mb_state.integral_error_nms_s = (adcs_vec3_t){0};
    }
}

// 5. Update Commanded Target with Slew Limit
adcs_vec3_t delta_target = adcs_vec3_sub(&mb_config.target_nms, &mb_state.commanded_target_nms);
double dist = adcs_vec3_norm(&delta_target);

if (dist > mb_config.target_slew_nms_per_cycle) {
    delta_target = adcs_vec3_scale(&delta_target, mb_config.target_slew_nms_per_cycle / dist);
}
mb_state.commanded_target_nms = adcs_vec3_add(&mb_state.commanded_target_nms, &delta_target);

// 6. Compute Error
error_nms = adcs_vec3_sub(&momentum_nms, &mb_state.commanded_target_nms);
norm_error = adcs_vec3_norm(&error_nms);

// 7. Mode Transitions
if (mb_state.mode == MB_RAMP) {
    if (norm_error <= mb_config.enter_error_nms) {
        mb_state.mode = MB_BIAS;
        mb_state.settled = 0;
    }
} else if (mb_state.mode == MB_BIAS) {
    if (norm_error <= mb_config.enter_error_nms) {
        mb_state.settled++;
        if (mb_state.settled >= mb_config.settle_cycles) {
            mb_state.mode = MB_HOLD;
        }
    } else {
        mb_state.settled = 0;
    }
} else if (mb_state.mode == MB_HOLD) {
    if (norm_error >= mb_config.exit_error_nms) {
        mb_state.mode = MB_BIAS;
        mb_state.settled = 0;
    }
}

// 8. Calculate Torque
adcs_vec3_t prev_integral = mb_state.integral_error_nms_s;
adcs_vec3_t kp_term = (adcs_vec3_t){0};
adcs_vec3_t ki_term = (adcs_vec3_t){0};
adcs_vec3_t pi_torque = (adcs_vec3_t){0};

if (mb_state.mode == MB_RAMP) {
    // RAMP: Proportional only, clear integral
    mb_state.integral_error_nms_s = (adcs_vec3_t){0};
    kp_term = adcs_vec3_scale(&error_nms, -mb_config.kp_s_inv);
    torque_nm = kp_term;
} else {
    // BIAS/HOLD: PI Control
    // Update Integral
    adcs_vec3_t error_dt = adcs_vec3_scale(&error_nms, mb_config.dt_s);
    adcs_vec3_t proposed_integral = adcs_vec3_add(&mb_state.integral_error_nms_s, &error_dt);

    // Clamp Integral
    for (int i = 0; i < 3; ++i) {
        double val = i == 0 ? proposed_integral.x : (i == 1 ? proposed_integral.y : proposed_integral.z);
        double limit = mb_config.integral_limit_nms_s;
        if (val > limit) val = limit;
        else if (val < -limit) val = -limit;

        if (i == 0) mb_state.integral_error_nms_s.x = val;
        else if (i == 1) mb_state.integral_error_nms_s.y = val;
        else mb_state.integral_error_nms_s.z = val;
    }

    kp_term = adcs_vec3_scale(&error_nms, -mb_config.kp_s_inv);
    ki_term = adcs_vec3_scale(&mb_state.integral_error_nms_s, -mb_config.ki_s2_inv);
    pi_torque = adcs_vec3_add(&kp_term, &ki_term);

    // Saturation Detection and Freeze Logic
    for (int i = 0; i < 3; ++i) {
        double p_val = i == 0 ? pi_torque.x : (i == 1 ? pi_torque.y : pi_torque.z);
        double limit = mb_config.torque_limit_nm;

        if (fabs(p_val) > limit) {
            sat_mask |= (1U << i);

            // Check if integral update drives it farther into saturation
            double old_ki_contrib = i == 0 ? (-mb_config.ki_s2_inv * prev_integral.x) : (i == 1 ? (-mb_config.ki_s2_inv * prev_integral.y) : (-mb_config.ki_s2_inv * prev_integral.z));
            double new_ki_contrib = i == 0 ? (-mb_config.ki_s2_inv * mb_state.integral_error_nms_s.x) : (i == 1 ? (-mb_config.ki_s2_inv * mb_state.integral_error_nms_s.y) : (-mb_config.ki_s2_inv * mb_state.integral_error_nms_s.z));

            if (fabs(new_ki_contrib) > fabs(old_ki_contrib)) {
                // Freeze axis: use previous integral for torque
                double frozen_torque = old_ki_contrib; // Since proportional term is ignored for this axis in freeze? 
                // Demand says "recompute its torque from the previous integral". 
                // This implies Torque_i = -Ki * PrevIntegral_i.
                // It does NOT say to add the proportional term.

                if (i == 0) torque_nm.x = frozen_torque;
                else if (i == 1) torque_nm.y = frozen_torque;
                else torque_nm.z = frozen_torque;
            } else {
                if (i == 0) torque_nm.x = p_val;
                else if (i == 1) torque_nm.y = p_val;
                else torque_nm.z = p_val;
            }
        } else {
            if (i == 0) torque_nm.x = p_val;
            else if (i == 1) torque_nm.y = p_val;
            else torque_nm.z = p_val;
        }
    }
}

// 9. Publish Output
mb_output.mode = mb_state.mode;
mb_output.settled = mb_state.settled;
mb_output.saturation_mask = sat_mask;
mb_output.momentum_nms = momentum_nms;
mb_output.commanded_target_nms = mb_state.commanded_target_nms;
mb_output.error_nms = error_nms;
mb_output.integral_error_nms_s = mb_state.integral_error_nms_s;
mb_output.torque_nm = torque_nm;

