    double err_i = (i == 0) ? mb_output.error_nms.x : (i == 1) ? mb_output.error_nms.y : mb_output.error_nms.z;
    double integ_prev_i = (i == 0) ? integral_prev.x : (i == 1) ? integral_prev.y : integral_prev.z;
    double integ_new_i = (i == 0) ? integral_new.x : (i == 1) ? integral_new.y : integral_new.z;

    double old_contrib = -mb_config.kp_s_inv * err_i - mb_config.ki_s2_inv * integ_prev_i;
    double new_contrib = -mb_config.kp_s_inv * err_i - mb_config.ki_s2_inv * integ_new_i;

    if (fabs(new_contrib) > mb_config.torque_limit_nm) {
        sat_mask |= (uint32_t)(1U << i);
    }

    if (((sat_mask >> i) & 1U) && (fabs(new_contrib) > fabs(old_contrib))) {
        if (i==0) torque_final.x = old_contrib;
        else if (i==1) torque_final.y = old_contrib;
        else torque_final.z = old_contrib;
    } else {
        if (i==0) torque_final.x = new_contrib;
        else if (i==1) torque_final.y = new_contrib;
        else torque_final.z = new_contrib;
    }
}

mb_state.integral_error_nms_s = integral_new;

mb_output.mode = mb_state.mode;
mb_output.settled = mb_state.settled;
mb_output.saturation_mask = sat_mask;
mb_output.commanded_target_nms = mb_state.commanded_target_nms;
mb_output.integral_error_nms_s = mb_state.integral_error_nms_s;
mb_output.torque_nm = torque_final;
